from typing import Any, Dict, Iterable, List, Mapping, Optional, Sequence, Set, Tuple, Union


def round_div(numerator: int, denominator: int, mode: str = "half_up") -> int:
    """
    Divide two integers and round the quotient to an integer, using exact integer
    arithmetic (no floats). `denominator` must be positive.

    Rounding modes:
      * "half_up"   - round to the nearest integer; exact halves are rounded up (default)
      * "half_even" - round to the nearest integer; exact halves go to the even neighbour
      * "floor"     - round towards negative infinity
      * "ceiling"   - round towards positive infinity

    Raises ValueError if `denominator` <= 0 or `mode` is not one of the names above.

    Examples:
        round_div(7, 2) == 4
        round_div(5, 2, "half_even") == 2
        round_div(-7, 2, "floor") == -4
    """
    if denominator <= 0:
        raise ValueError("denominator must be positive")

    valid_modes = {"half_up", "half_even", "floor", "ceiling"}
    if mode not in valid_modes:
        raise ValueError(f"mode must be one of {valid_modes}")

    if mode == "floor":
        # Python's // is already floor division
        return numerator // denominator

    if mode == "ceiling":
        # ceil(a/b) = -floor(-a/b)
        return -(-numerator // denominator)

    if mode == "half_up":
        # Symmetric rounding: round half away from zero
        # Use divmod to get quotient (floored) and remainder
        q, r = divmod(numerator, denominator)
        if r == 0:
            return q
        # Check if we're at or past the halfway point
        if 2 * r >= denominator:
            # Round away from zero
            if numerator >= 0:
                return q + 1
            else:
                # q is already floored (more negative), so q is away from zero
                return q
        else:
            # Round toward zero (truncate)
            return q

    if mode == "half_even":
        # Banker's rounding: round half to nearest even
        q, r = divmod(numerator, denominator)
        if r == 0:
            return q
        if 2 * r == denominator:
            # Exact half: round to even
            if q % 2 == 0:
                return q
            else:
                # q is odd, round to even neighbor
                # For both positive and negative, q+1 is the even neighbor
                # because q is floored
                return q + 1
        elif 2 * r > denominator:
            # More than half: round away from zero
            if numerator >= 0:
                return q + 1
            else:
                return q
        else:
            # Less than half: truncate toward zero
            return q

    raise ValueError("unreachable")
